class BookManagement:
    def __init__(self):
        self._inventory = {}

    def add_book(self, title, quantity=1):
        if self._contains_book(title):
            self._increment_quantity(title, quantity)
        else:
            self._set_quantity(title, quantity)

    def remove_book(self, title, quantity):
        if not self._contains_book(title) or self._get_quantity(title) < quantity:
            raise ValueError("Cannot remove book due to insufficient quantity or missing book")
        self._decrement_quantity(title, quantity)
        if self._get_quantity(title) == 0:
            self._delete_book(title)

    def view_inventory(self):
        return dict(self._inventory)

    def view_book_quantity(self, title):
        return self._get_quantity(title)

    def _contains_book(self, title):
        return title in self._inventory

    def _increment_quantity(self, title, quantity):
        self._inventory[title] += quantity

    def _set_quantity(self, title, quantity):
        self._inventory[title] = quantity

    def _decrement_quantity(self, title, quantity):
        self._inventory[title] -= quantity

    def _delete_book(self, title):
        del self._inventory[title]

    def _get_quantity(self, title):
        if not self._contains_book(title):
            return 0
        return self._inventory[title]
